import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { apisPath, paths } from "../../utils/path";
import http, { uploadImage } from "../../services/utility";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { useDispatch } from "react-redux";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";

export default function SubscriptionPlan() {
  const navigate = useNavigate();
  const newBannerRef = useRef(null);
  const dispatch = useDispatch();
  const [cardData, setCardData] = useState([]);
  const [subscriptionBanner, setSubscriptionBanner] = useState(null);
  const [bannerList, setBannerList] = useState([]);

  useEffect(() => {
    getData();
  }, []);

  const uploadBanner = async (url) => {
    await http
      .post(apisPath?.admin?.subscriptionBanners, {
        image: url,
      })
      .then(async (res) => {
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        setSubscriptionBanner(null);
        getData();
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const deleteBanner = async (id) => {
    await http
      .delete(`${apisPath?.admin?.subscriptionBanners}/${id}`)
      .then(async (res) => {
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const getData = async () => {
    await http
      .get(apisPath?.admin?.plans)
      .then(async (res) => {
        setCardData(res?.data?.plans);
      })
      .catch((err) => {
        console.log(err);
      });

    await http
      .get(apisPath?.admin?.subscriptionBanners)
      .then(async (res) => {
        // console.log(res?.data);
        setBannerList(res?.data?.subscriptionBanners);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  return (
    <div className="subscription_plan">
      <h3 className="subscription_plan__heading page_heading">
        Subscription plans
      </h3>
      <button
        className="button-red"
        onClick={() =>
          navigate(
            `/${paths?.front?.user?.subscription_plan}/${paths?.front?.user?.add_subscription_plan}`,
            {
              state: { editable: false },
            }
          )
        }
      >
        Add Plan
      </button>
      <div className="subscription_plan__content">
        {cardData?.length > 0 ? (
          cardData?.map((card, index) => {
            return <Card key={index} data={card} />;
          })
        ) : (
          <div className="no_data_found">No Data Found</div>
        )}
      </div>
      <div className="subscription_plan__banner">
        <h4 className="notification__heading page_subheading">Banner</h4>
        <div className="subscription_plan__banner__content">
          <div
            className="subscription_plan__banner__content__upload_logo"
            onClick={() => newBannerRef?.current?.click()}
          >
            {!subscriptionBanner && (
              <>
                <FileUploadIcon />
                <span>Upload new banner</span>
              </>
            )}
          </div>
          <div className="subscription_plan__banner__content__uploaded_logo">
            {bannerList?.length > 0 ? (
              bannerList?.map((data, index) => {
                return (
                  <div key={index}>
                    <div className="subscription_plan__banner__content__uploaded_logo__logo">
                      <img src={data?.image} />
                    </div>
                    <button
                      className="button-red"
                      onClick={() => deleteBanner(data?.id)}
                    >
                      Delete
                    </button>
                  </div>
                );
              })
            ) : (
              <div className="no_data_found">No Data Found</div>
            )}
          </div>

          <input
            type="file"
            style={{ display: "none" }}
            ref={newBannerRef}
            onChange={async (e) => {
              await uploadImage(e)
                .then((res) => {
                  setSubscriptionBanner(res?.url);
                  uploadBanner(res?.url);
                })
                .catch((err) => {
                  console.log(err);
                });
            }}
          />
        </div>
      </div>
    </div>
  );
}

const Card = ({ data }) => {
  const navigate = useNavigate();

  return (
    <div className="subscription_plan__card">
      <div className="subscription_plan__card__term">
        <h3>{data?.duration}</h3>
        <span>Plan for you just in</span>
      </div>
      <h3 className="subscription_plan__card__fee">&#8377;{data?.price}</h3>
      <div className="subscription_plan__card__content">
        {data?.benefits?.map((item, index) => {
          return <p>{item}</p>;
        })}
      </div>
      <button
        className="button-red"
        onClick={() =>
          navigate(`/${paths?.front?.user?.subscription_plan}/${data?.id}`, {
            state: { data: data, editable: true },
          })
        }
      >
        Edit
      </button>
    </div>
  );
};
